#include <bits/stdc++.h>
using namespace std;
class Solution {
 int K;string digits;int memo[12][23][21][2];
 int dfs(int pos,int diff,int rem,int started,bool tight){if(pos==(int)digits.size())return started&&diff==0&&rem==0;if(!tight&&memo[pos][diff+11][rem][started]!=-1)return memo[pos][diff+11][rem][started];int ans=0,lim=tight?digits[pos]-'0':9;for(int d=0;d<=lim;++d){int st=started||d!=0,nd=diff+(st?(d%2?1:-1):0);if(nd < -11||nd>11)continue;ans+=dfs(pos+1,nd,(rem*10+d)%K,st,tight&&d==lim);}if(!tight)memo[pos][diff+11][rem][started]=ans;return ans;}
 int count(int x){if(x<=0)return 0;digits=to_string(x);memset(memo,-1,sizeof(memo));return dfs(0,0,0,0,true);}
 public:int numberOfBeautifulIntegers(int low,int high,int k){K=k;return count(high)-count(low-1);}
};
